console.log("[ApplyPilot AI] Service Worker running...");chrome.runtime.onInstalled.addListener(()=>{chrome.sidePanel&&chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).catch(e=>console.error("[ApplyPilot] Failed to set side panel behavior:",e))});chrome.tabs.onUpdated.addListener((e,l,o)=>{l.status==="complete"&&o.url&&(console.log("[ApplyPilot] Tab updated:",o.url),chrome.runtime.sendMessage({action:"TAB_CHANGED",url:o.url,tabId:e}).catch(()=>{}))});
